import AppKit
let old=URL(fileURLWithPath:CommandLine.arguments[1]),new=URL(fileURLWithPath:CommandLine.arguments[2])
func load(_ root:URL,_ name:String)throws->NSBitmapImageRep{guard let image=NSBitmapImageRep(data:try Data(contentsOf:root.appending(path:name)))else{throw CocoaError(.fileReadCorruptFile)};return image}
func rgb(_ image:NSBitmapImageRep,_ x:Int,_ y:Int)->[Double]{let c=image.colorAt(x:x,y:y)!.usingColorSpace(.sRGB)!;return [c.redComponent,c.greenComponent,c.blueComponent].map{Double($0)*255}}
func distribution(_ image:NSBitmapImageRep)->[String:Double]{var sum=0.0,squares=0.0,n=0.0;for y in 180..<260{for x in 64..<624{let c=rgb(image,x,y),v=c[0]*0.2126+c[1]*0.7152+c[2]*0.0722;sum+=v;squares+=v*v;n+=1}};return ["mean":sum/n,"stddev":sqrt(max(0,squares/n-pow(sum/n,2)))]}
var rows=[[String:Any]]()
for border in ["on","off"] {let name="border-"+border+"-desktop.png",a=try load(old,name),b=try load(new,name),c=try load(new,"border-"+border+"-fullscreen.png");precondition(a.pixelsWide==b.pixelsWide&&a.pixelsHigh==b.pixelsHigh);var total=0.0,maximum=0.0,pixels=0;for y in 0..<a.pixelsHigh{for x in 0..<a.pixelsWide{let l=rgb(a,x,y),r=rgb(b,x,y);var changed=false;for k in 0..<3{let d=abs(l[k]-r[k]);total+=d;maximum=max(maximum,d);changed=changed||d>0.001};if changed{pixels+=1}}};rows.append(["border":border,"ordinary_changed_pixels":pixels,"ordinary_mean_abs_difference_255":total/Double(a.pixelsWide*a.pixelsHigh*3),"ordinary_max_abs_difference_255":maximum,"ordinary_blank_patch_luminance":distribution(b),"fullscreen_blank_patch_luminance":distribution(c),"blank_patch_pixels":[64,180,624,260]])}
let data=try JSONSerialization.data(withJSONObject:rows,options:[.prettyPrinted,.sortedKeys]);try data.write(to:new.appending(path:"pixels.json"));print(String(data:data,encoding:.utf8)!)
